// ============================================================
// Dynamic AI Prompt Generator — versão 3.1
// Correção: detector de conteúdo insuficiente + aviso ao LLM
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json;

  const urgencyContext = j.preScore >= 9
    ? 'EXTREME URGENCY — Black Swan event. This could reshape global markets immediately.'
    : j.preScore === 8
    ? 'HIGH URGENCY — Major market mover. Significant geopolitical or crypto impact expected.'
    : 'RELEVANT — Notable development worth monitoring, but not an immediate market shock.';

  // ✅ NOVO v3.1 — Detector de conteúdo insuficiente
  const contentWarning = j.contentSnippet && j.contentSnippet.length < 200
    ? 'WARNING: The content snippet is very short (' + j.contentSnippet.length + ' chars). Write only what is explicitly stated above. DO NOT invent or assume any facts. If there is not enough information for 3 full paragraphs, write shorter paragraphs and set score to 3 or below.'
    : 'Content is sufficient — write all 3 paragraphs fully based on the article data.';

  const userPrompt = `
You are a Senior Breaking News Editor specializing in Global Geopolitics and Bitcoin Markets.

ARTICLE DATA:
- Title: ${j.title}
- Source: ${j.source} (${j.domain})
- Published: ${j.pubDate}
- Pre-Score (local urgency filter): ${j.preScore}/10
- Urgency context: ${urgencyContext}
- Content warning: ${contentWarning}
- Content: ${j.contentSnippet}
- Original URL: ${j.link}

YOUR TASK:
Analyze the article above and return ONLY a raw valid JSON object.
No markdown. No backticks. No explanation. No text before or after the JSON.
Your entire response must be directly parseable by JSON.parse().

REQUIRED JSON FIELDS:
{
  "headline": "string — High-impact headline in English, max 15 words, communicates urgency and consequence",
  "hook": "string — One sharp opening sentence in English, max 25 words, must create tension or surprise",
  "conteudo_blog": "string — Exactly 3 paragraphs in English, total between 150 and 250 words",
  "tags": "string — Space-separated hashtags in English, max 5 tags, e.g. #Bitcoin #Geopolitics #Fed",
  "score": "integer — Your final urgency score from 1 to 10, whole number only",
  "should_alert": "boolean — true if your score is 8 or higher, false otherwise",
  "link": "${j.link}"
}

SCORING GUIDE — be precise, do not inflate scores:
- 9-10: True Black Swan — active major war escalation, central bank collapse, exchange hack above $1B, emergency G7 response
- 7-8:  Market mover — ETF approval/rejection, Fed rate decision, country-wide crypto ban, major sanctions package, nuclear threat
- 5-6:  Geopolitically relevant — elections, regional conflicts, regulatory proposals, significant political shifts
- 3-4:  Domestic politics — local legislation, state-level decisions, party disputes without direct market impact
- 1-2:  Low impact — price opinions, minor altcoin updates, routine political statements, soft feature stories

STRICT RULES — violations will break the pipeline:
- score MUST be a whole INTEGER — never 7.5, never 0.8, never a string
- should_alert MUST be a boolean true or false — never a string "true"
- ALL text fields (headline, hook, conteudo_blog, tags) MUST be written in English
- conteudo_blog MUST be between 150 and 250 words total — count before responding
- NEVER copy sentences verbatim from the source content — aggressively paraphrase
- NEVER invent facts not present in the article data above
- link MUST be the exact original URL provided — do not shorten, alter or invent it
- tags must use the # symbol and relate directly to the article topic
`.trim();

  results.push({
    json: {
      link:           j.link,
      title:          j.title,
      source:         j.source,
      domain:         j.domain,
      isTier1:        j.isTier1,
