      pubDate:        j.pubDate,
      preScore:       j.preScore,
      isVip:          j.isVip,
      contentSnippet: j.contentSnippet,
      userPrompt:     userPrompt,
    }
  });
}

const hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
console.log('Prompt Generator ' + hora + ': ' + results.length + ' prompts gerados');
results.forEach((r, i) => {
  console.log('  [' + (i+1) + '] preScore ' + r.json.preScore + '/10 | content ' + (r.json.contentSnippet || '').length + ' chars | ' + (r.json.title || '').substring(0, 50) + '...');
});

return results;

for (const item of $input.all()) {
  // O SEGREDO ESTÁ AQUI: Apontar diretamente para 'data.content'
  let text = item.json.data.content || "";

  // 1. O Exterminador de Tickers do CoinDesk
  text = text.replace(/\[[A-Za-z0-9\s]+?\$[\d,\.]+\s+[\d,\.]+?%\]/gi, '');

  // 2. O Destruidor de Links Gigantes Markdown
  text = text.replace(/\[.*?\]\((https?:\/\/[^\s]+)\)/gi, '');

  // 3. Limpeza de menus inúteis do CoinDesk
  text = text.replace(/Share this article/gi, '');
  text = text.replace(/Copy link/gi, '');

  // Cria uma nova variável com o texto limpo para o Llama 3
  item.json.clean_content = text.trim();
}

return $input.all();

let texto = $input.item.json.output || "";

// Limpa lixo de markdown
texto = texto.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();

try {
    // Tenta o parse padrão primeiro
    $input.item.json.dados_prontos = JSON.parse(texto);
} catch (e) {
    // Se falhar, usamos uma extração "inteligente" que busca até a próxima chave ou o fim do JSON
    $input.item.json.dados_prontos = {};

    const extrair = (chave) => {
        // Busca o conteúdo ignorando aspas internas, parando apenas quando encontra ", "chave": ou o fim }
        const regex = new RegExp(`"${chave}"\\s*:\\s*"([\\s\\S]*?)"(?=\\s*,?\\s*"[a-zA-Z0-9_]+"\\s*:|\\s*})`, "i");
        const match = texto.match(regex);
        return match ? match[1] : null;
    };

    let blog = extrair("conteudo_blog");
    let head = extrair("headline");
    let summ = extrair("summary");
    let hook = extrair("hook");

    if (blog) $input.item.json.dados_prontos.content = blog.replace(/\\"/g, '"').replace(/\\n/g, '\n');
    if (head) $input.item.json.dados_prontos.title = head.replace(/\\"/g, '"');
    if (summ) $input.item.json.dados_prontos.summary = summ.replace(/\\"/g, '"').replace(/\\n/g, '\n');
    if (hook) $input.item.json.dados_prontos.hook = hook.replace(/\\"/g, '"');
}

// Garante que o n8n sempre veja os nomes certos para a Ponte Nostr
$input.item.json.dados_prontos.content = $input.item.json.dados_prontos.content || $input.item.json.dados_prontos.conteudo_blog;
$input.item.json.dados_prontos.title = $input.item.json.dados_prontos.title || $input.item.json.dados_prontos.headline;

return $input.item;

