  "primary_keywords": [
    "world", "geopolitics", "global", "conflict", "war", "guerra", "conflito", "mundo", "bitcoin", "btc", "crypto", "criptomoeda", "criptomoedas", "blockchain", "brasil", "brazil", "brasília", "lula", "stf", "banco central", "haddad", "china", "india", "asia", "us", "eua", "russia", "putin", "biden", "trump"
  ],
  "secondary_keywords": [
    "military", "strike", "missile", "treaty", "sanction", "election", "ataque", "sanção", "eleição", "etf", "halving", "regulation", "mining", "sec", "binance", "fed", "selic", "inflation", "inflação", "pib", "gdp", "trade", "embargo", "tensão", "diplomacia", "acordo", "juros", "taxa", "mercado"
  ]
};

const vipKeywords = ["bitcoin", "btc", "crypto", "criptomoeda", "criptomoedas"];
const highImpactKeywords = ["war", "guerra", "ataque", "strike", "sanction", "sanção", "crash", "collapse", "colapso"];

const calcPreScore = (item, searchContext) => {
  let score = 0;

  // 1. PESO DE RECÊNCIA (O coração do filtro)
  if (item.pubDate) {
    const ageInHours = (Date.now() - new Date(item.pubDate).getTime()) / (1000 * 60 * 60);

    if (ageInHours <= 1) score += 6;      // Saiu agora (até 1h): Bônus máximo
    else if (ageInHours <= 3) score += 4; // Fresca (1h a 3h)
    else if (ageInHours <= 6) score += 2; // Morna (3h a 6h)
    else if (ageInHours <= 12) score += 1;// Antiga (6h a 12h)
    // Notícias com mais de 12h não ganham bônus de tempo
  }

  // 2. PESO DE CONTEÚDO (Impacto e VIP)
  if (highImpactKeywords.some(kw => searchContext.includes(kw))) score += 2;
  if (vipKeywords.some(kw => searchContext.includes(kw))) score += 2;

  // 3. BÔNUS DE AUTORIDADE
  if (item.isTier1 === true) score += 1;

  return score; // Sem limite de 10 para permitir que a recência seja o desempate real
};

const candidates = [];

for (const item of $input.all()) {
  const json = item.json;
  const title = json.title || "";
  const snippet = json.contentSnippet || "";
  const searchContext = `${title} ${snippet}`.toLowerCase();

  const isVip = vipKeywords.some(kw => searchContext.includes(kw));
  const hasPrimary = config.primary_keywords.some(kw => searchContext.includes(kw));
  const hasSec = config.secondary_keywords.some(kw => searchContext.includes(kw));

  // Filtro de relevância: VIP ou Primária + Secundária
  if (!isVip && !(hasPrimary && hasSec)) {
    continue;
  }

  const preScore = calcPreScore(json, searchContext);

  // Threshold: Ajustado para 4. 
  // Uma notícia de Bitcoin (2 pts) que saiu agora (6 pts) somaria 8. Passa com folga.
  if (preScore < 4) { 
    continue;
  }

  candidates.push({
    json: {
      ...json,
      preScore: preScore,
      isVip: isVip,
      bbn_config: config
    }
  });
}

// ORDENAÇÃO: O mais pesado (Score alto) no topo.
// Como o Score agora é dominado pela recência, as notícias novas "atropelam" as velhas.
const sortedCandidates = candidates.sort((a, b) => b.json.preScore - a.json.preScore);

return sortedCandidates;

// Função auxiliar para limpar tags HTML
const stripHTML = (html) => {
  if (!html) return '';
  return html.replace(/<[^>]*>/g, '').trim();
};

const cleanedItems = [];

for (const item of $input.all()) {
  const json = item.json;

