  'reuters.com', 'bbc.co.uk', 'bbc.com',
  'apnews.com', 'aljazeera.com', 'theguardian.com',
  'ft.com', 'zerohedge.com', 'al-monitor.com', 'cnbc.com'
];

  // 1. Extração de Fonte (Mantive sua lógica que já é excelente)
  const source = json.creator || json['dc:creator'] || json.author || 'Unknown';

  // 2. Extração de Conteúdo (AGORA BLINDADA PARA OS 10 FEEDS)
  // Ele procura a informação na ordem das chaves mais ricas para as mais simples
  let rawContent = json['content:encoded'] || json.contentSnippet || json.content || json.description || '';
  const contentSnippet = stripHTML(rawContent);

  // 3. Extração de Data (Com fallback de segurança caso o feed não envie data)
  const pubDate = json.isoDate || json.pubDate || new Date().toISOString();

  // 4. Montagem do payload limpo
  cleanedItems.push({
    json: {
      link: json.link,                    
      title: stripHTML(json.title), // Limpamos o título também, alguns feeds enviam sujeira aqui               
      contentSnippet: contentSnippet,     
      pubDate: pubDate,                   
      source: source                      
    }
  });
}

return cleanedItems;

